CREATE DEFINER=`root`@`%` PROCEDURE `tx_update_thanh_du_md5`(IN user_name VARCHAR(45),
    IN in_number INT,
    IN total_betting BIGINT,
    IN current_reference_id BIGINT,
    IN in_references VARCHAR(512),
    IN in_type TINYINT)
BEGIN
  IF
(
SELECT 1 = 1
FROM thanh_du_md5
WHERE thanh_du_md5.user_name = user_name
  AND thanh_du_md5.type = in_type
  AND thanh_du_md5.`last_update` >= CURDATE()) THEN
BEGIN
UPDATE thanh_du_md5
SET thanh_du_md5.`number`       = in_number,
    thanh_du.total_betting      = total_betting,
    thanh_du_md5.last_reference = current_reference_id,
    thanh_du_md5.`references`   = in_references
WHERE thanh_du_md5.user_name = user_name
  AND thanh_du_md5.type = in_type
  AND thanh_du_md5.`last_update` >= CURDATE();
END;
ELSE
BEGIN
INSERT INTO thanh_du_md5(`user_name`, `number`, `total_betting`, `last_reference`, `references`, `last_update`, `type`)
VALUES (user_name, in_number, total_betting, current_reference_id, in_references, CURRENT_TIMESTAMP(), in_type);
END;
END IF;
END ;;
DELIMITER ;
